package io.github.ningpp.compat;

/**
 * Replacement for System.UIntPtr (generated by CSharpToJava converter): an unsigned
 * integer whose bit width matches a pointer (64 bits on this platform). Java has no
 * unsigned integer types, so the value is carried in a long and rendered through the
 * unsigned helpers of {@link ULong}.
 */
public final class UIntPtr implements Comparable<UIntPtr>, IEquatable<UIntPtr> {

    /** C# UIntPtr.Zero — the unsigned integer whose value is zero. */
    public static final UIntPtr Zero = new UIntPtr(0L);

    /** C# UIntPtr.Size — the size of this type in bytes (8 on a 64-bit platform). */
    public static final int Size = Long.BYTES;

    private final long value;

    /**
     * Creates a pointer-sized unsigned integer from an unsigned 64-bit value.
     *
     * @param value The unsigned value to represent (bits, not magnitude).
     */
    public UIntPtr(long value) {
        this.value = value;
    }

    /**
     * Creates a pointer-sized unsigned integer from an unsigned 32-bit value.
     *
     * @param value The unsigned value to represent (bits, not magnitude).
     */
    public UIntPtr(int value) {
        this.value = value & 0xFFFFFFFFL;
    }

    /**
     * Creates a pointer-sized unsigned integer from the boxed representation used by
     * the generated code: another UIntPtr or any Number.
     *
     * @param value The value to represent.
     */
    public UIntPtr(Object value) {
        if (value == null) {
            throw new ArgumentNullException("value");
        }
        if (value instanceof UIntPtr pointer) {
            this.value = pointer.value;
        } else if (value instanceof Number number) {
            this.value = number.longValue();
        } else {
            throw new ArgumentException("Cannot convert " + value.getClass().getName() + " to UIntPtr.");
        }
    }

    /**
     * C# UIntPtr.Size.
     *
     * @return The size of this type in bytes.
     */
    public static int getSize() {
        return Size;
    }

    /**
     * C# UIntPtr.ToUInt64() — the value as an unsigned 64-bit integer, whose bits are
     * returned in a Java long.
     *
     * @return The value of this instance as an unsigned 64-bit integer.
     */
    public long toUInt64() {
        return value;
    }

    /**
     * The value carried by this instance, for call sites converted from a Value-like
     * property.
     *
     * @return The value of this instance as an unsigned 64-bit integer.
     */
    public long getValue() {
        return value;
    }

    /**
     * C# UIntPtr.ToUInt32() — the low 32 bits of the value as an unsigned 32-bit
     * integer, whose bits are returned in a Java int.
     *
     * @return The value of this instance as an unsigned 32-bit integer.
     */
    public int toUInt32() {
        return (int) value;
    }

    /**
     * C# UIntPtr.Add(UIntPtr pointer, int offset).
     *
     * @param pointer The pointer-sized unsigned integer to add to.
     * @param offset The number to add.
     * @return A new UIntPtr holding the sum.
     */
    public static UIntPtr add(UIntPtr pointer, int offset) {
        if (pointer == null) throw new ArgumentNullException("pointer");
        return new UIntPtr(pointer.value + offset);
    }

    /**
     * C# UIntPtr.Add(UIntPtr pointer, int offset) for an offset that is already a long.
     *
     * @param pointer The pointer-sized unsigned integer to add to.
     * @param offset The number to add.
     * @return A new UIntPtr holding the sum.
     */
    public static UIntPtr add(UIntPtr pointer, long offset) {
        if (pointer == null) throw new ArgumentNullException("pointer");
        return new UIntPtr(pointer.value + offset);
    }

    /**
     * C# UIntPtr.Subtract(UIntPtr pointer, int offset).
     *
     * @param pointer The pointer-sized unsigned integer to subtract from.
     * @param offset The number to subtract.
     * @return A new UIntPtr holding the difference.
     */
    public static UIntPtr subtract(UIntPtr pointer, int offset) {
        if (pointer == null) throw new ArgumentNullException("pointer");
        return new UIntPtr(pointer.value - offset);
    }

    /**
     * C# UIntPtr.Subtract(UIntPtr pointer, int offset) for an offset that is already a
     * long.
     *
     * @param pointer The pointer-sized unsigned integer to subtract from.
     * @param offset The number to subtract.
     * @return A new UIntPtr holding the difference.
     */
    public static UIntPtr subtract(UIntPtr pointer, long offset) {
        if (pointer == null) throw new ArgumentNullException("pointer");
        return new UIntPtr(pointer.value - offset);
    }

    /**
     * The instance form of C# UIntPtr.Add.
     *
     * @param offset The number to add.
     * @return A new UIntPtr holding the sum.
     */
    public UIntPtr add(long offset) {
        return new UIntPtr(value + offset);
    }

    /**
     * The instance form of C# UIntPtr.Subtract.
     *
     * @param offset The number to subtract.
     * @return A new UIntPtr holding the difference.
     */
    public UIntPtr subtract(long offset) {
        return new UIntPtr(value - offset);
    }

    /**
     * C# UIntPtr.Equals(object) — true when the other object is a UIntPtr with the
     * same value.
     *
     * @param obj The object to compare with this instance.
     * @return true when the other object represents the same unsigned value.
     */
    @Override
    public boolean equals(Object obj) {
        return obj instanceof UIntPtr other && other.value == value;
    }

    /**
     * C# IEquatable&lt;UIntPtr&gt;.Equals(UIntPtr) — true when the other pointer holds
     * the same value.
     *
     * @param other The pointer to compare with this instance.
     * @return true when the other pointer represents the same unsigned value.
     */
    @Override
    public boolean equalsTo(UIntPtr other) {
        return other != null && other.value == value;
    }

    /**
     * C# UIntPtr.GetHashCode().
     *
     * @return A hash code for this instance.
     */
    @Override
    public int hashCode() {
        return Long.hashCode(value);
    }

    /**
     * C# UIntPtr.CompareTo(UIntPtr) — compares the unsigned values of the two
     * pointers.
     *
     * @param other The pointer to compare with this instance.
     * @return A negative integer, zero, or a positive integer as this instance is
     *         less than, equal to, or greater than the other pointer.
     */
    @Override
    public int compareTo(UIntPtr other) {
        if (other == null) throw new ArgumentNullException("other");
        return Long.compareUnsigned(value, other.value);
    }

    /**
     * C# UIntPtr.ToString() — the value rendered as an unsigned decimal number.
     *
     * @return The unsigned decimal representation of this instance.
     */
    @Override
    public String toString() {
        return ULong.toString(value);
    }
}
